  "already knows the shelf.": "badaki apalean zer dagoen.",
  "Samsoom knows our catalogue, grades, hours and shipping. It finds the part, explains the grade, and hands you to a person on WhatsApp the second you need one.": "Samsoomek gure katalogoa, kalitateak, ordutegia eta bidalketak ezagutzen ditu. Pieza aurkitzen du, kalitatea azaltzen du eta behar duzun unean WhatsApp bidez pertsona batekin jartzen zaitu.",
  "Do you have a Galaxy A54 battery?": "Baduzue Galaxy A54rako bateriarik?",
