  "Repairs you book on this device appear here with their job ticket.": "Gailu honetan erreserbatutako konponketak hemen agertzen dira, beren txartelarekin.",
  "Order": "Eskaera",
  "Each part’s warranty is on its label and invoice; bring the order number with the part.": "Pieza bakoitzaren bermea bere etiketan eta fakturan dago; ekarri eskaera-zenbakia piezarekin.",
  "Repairs are covered from the day you collect the phone. Bring this ticket.": "Konponketek telefonoa jasotzen duzun egunetik dute bermea. Ekarri txartel hau.",
  "We can’t find that number on this account. Check it, or send it to us on WhatsApp and we look it up.": "Ez dugu zenbaki hori kontu honetan aurkitu. Egiaztatu edo bidali WhatsApp bidez eta bilatuko dugu.",
