  "We reply by e-mail and WhatsApp, usually within one working day. Sign in with the same e-mail to see the result here.": "Posta elektronikoz eta WhatsApp bidez erantzuten dugu, normalean lanegun batean. Hasi saioa posta berarekin emaitza hemen ikusteko.",
