  "Marketing and offers": "Marketina eta eskaintzak",
  "Keeps the site running: your cart, language and sign-in.": "Webgunea martxan mantentzen du: saskia, hizkuntza eta saioa.",
  "Your cart, your language, your sign-in session and these privacy choices.": "Zure saskia, hizkuntza, saioa eta pribatutasun-aukera hauek.",
  "Currency, sounds, recent searches, starred parts and your devices.": "Moneta, soinuak, azken bilaketak, gogoko piezak eta zure gailuak.",
  "Which pages are opened and how fast they load. Never your name or contact.": "Zein orri irekitzen diren eta zein azkar kargatzen diren. Inoiz ez zure izena edo harremana.",
  "The kinds of parts you look at, to show matching offers.": "Begiratzen dituzun pieza motak, eskaintza egokiak erakusteko.",
  "Until you clear them (sign-in: until you sign out).": "Ezabatu arte (saioa: irten arte).",
  "12 months, or until you clear them.": "12 hilabete, edo ezabatu arte.",
  "13 months.": "13 hilabete.",
  "6 months.": "6 hilabete.",
  "Without them the cart would empty and the site would forget your language on every page.": "Haiek gabe saskia hustu egingo litzateke eta webguneak zure hizkuntza ahaztuko luke orri bakoitzean.",
  "So you do not have to set things up again on every visit.": "Bisita bakoitzean dena berriro ezarri behar ez izateko.",
  "To see which pages are slow or confusing and fix them.": "Zein orri diren motelak edo nahasgarriak ikusi eta konpontzeko.",
  "So the offers you see are for your phones, not random ones.": "Eskaintzak zure telefonoentzat izan daitezen, ez ausaz.",
  "You add a screen to the cart, open another page, and it is still there.": "Pantaila bat gehitzen duzu saskira, beste orri bat irekitzen duzu eta hor jarraitzen du.",
  "You searched \"A54 battery\" yesterday; today it is first in your recent searches.": "Atzo «A54 bateria» bilatu zenuen; gaur lehena da azken bilaketetan.",
  "We notice the Repair page loads slowly on phones and make it faster.": "Konponketa-orria telefonoetan motel kargatzen dela ikusten dugu eta azkarrago egiten dugu.",
  "You look at iPhone 13 screens; the next deal we show you is for that screen.": "iPhone 13 pantailak begiratzen dituzu; hurrengo eskaintza pantaila horrena da.",
