  "A guide to how the grades usually compare. Each part’s own label and warranty are on its page.": "Kalitateak normalean nola alderatzen diren gidatzeko. Pieza bakoitzaren etiketa eta bermea bere orrian daude.",
  "FROM FACTORY TO YOUR BENCH": "FABRIKATIK ZURE LAN-MAHAIRA",
