  "Thanks for the photo! I can’t look at photos right now, so send it to the team on WhatsApp and they will tell you the part and the price.": "Eskerrik asko argazkiagatik! Orain ezin ditut argazkiak ikusi; bidali taldeari WhatsApp bidez eta pieza eta prezioa esango dizkizute.",
  "Thanks for the photo! Send it to the team on WhatsApp and they will tell you the part and the price.": "Eskerrik asko argazkiagatik! Bidali taldeari WhatsApp bidez eta pieza eta prezioa esango dizkizute.",
