  "Reviews open once we have confirmed your order of this part, so every review is a verified purchase.": "Iritziak pieza honen eskaera berretsi ondoren irekitzen dira, beraz iritzi bakoitza erosketa egiaztatua da.",
  "Only customers who bought this part can review it, after we confirm their order.": "Pieza hau erosi duten bezeroek bakarrik balora dezakete, eskaera berretsi ondoren.",
