  'WORLDWIDE SHIPPING': 'MUNDU OSORAKO BIDALKETAK',
  'to your door.': 'zure ateraino.',
  'We ship parts every week to repair shops and traders across the Middle East, Africa, Europe and Asia: door to door with our partners, or with your own shipper.': 'Astero piezak bidaltzen ditugu Ekialde Hurbileko, Afrikako, Europako eta Asiako tailer eta saltzaileei: atez ate gure bazkideekin, edo zure garraiolariarekin.',
