  'About a week': 'Aste bat inguru',
  'Sea freight': 'Itsasoko garraioa',
  'Large orders by container, via Suez or East Africa.': 'Eskaera handiak edukiontzian, Suez edo Ekialdeko Afrikatik.',
  'A commercial invoice and packing list go with every shipment.': 'Bidalketa bakoitzak faktura komertziala eta paketatze-zerrenda ditu.',
  'Duties and taxes are paid by the receiver on arrival, unless we agree otherwise.': 'Muga-zergak eta zergak hartzaileak ordaintzen ditu iristean, beste zerbait adostu ezean.',
  'Some routes need the importer’s company registration for clearance; we tell you before we ship.': 'Bide batzuek inportatzailearen enpresa-erregistroa eskatzen dute aduanarako; bidali aurretik esaten dizugu.',
