  'Free check first': 'Lehenik doako egiaztapena',
  'Pick your phone first': 'Lehenik aukeratu zure telefonoa',
  'Your total appears here.': 'Zure guztizkoa hemen agertzen da.',
  'Parts in stock': 'Piezak stockean',
  'Note': 'Oharra',
  'TOTAL': 'GUZTIRA',
