  'MODEL': 'MODELOA',
  'Name': 'Izena',
  'All': 'Guztiak',
  'fitting': 'muntaketa',
  'Pick your phone and see every repair we do for it: the part in each grade, the fitting fee and the total, before you come in.': 'Aukeratu telefonoa eta ikusi konponketa guztiak: pieza maila bakoitzean, muntaketa-kuota eta guztizkoa, etorri aurretik.',
  'Every repair for the': 'Konponketa guztiak:',
  'Part price + fitting fee = your total. Prices are samples; the bench confirms the final price before starting.': 'Piezaren prezioa + muntaketa = zure guztizkoa. Adibide-prezioak; mahaiak azken prezioa berresten du hasi aurretik.',
  'The fee follows the price of the part. Our technician may adjust it up or down for the part and the work involved, and always tells you before starting.': 'Kuota piezaren prezioaren araberakoa da. Teknikariak egokitu dezake, eta beti esaten dizu hasi aurretik.',
  'Book this repair': 'Erreserbatu konponketa hau',
  'Diagnosis first: we check it, then quote. Diagnosis is free when you repair with us.': 'Lehenik diagnostikoa: egiaztatu eta aurrekontua. Doan gurekin konpontzen baduzu.',
  'STEP 2 · THE REPAIR': '2. URRATSA · KONPONKETA',
  'Book a check': 'Erreserbatu egiaztapena',
  'No part in stock for this model right now: we can order it.': 'Orain ez dago piezarik modelo honetarako: eska dezakegu.',
