  'Buying for a business? Add your company, then apply for trade prices: once approved you see both prices in the shop.': 'Negozio baterako erosten duzu? Gehitu enpresa eta eskatu merkatari-prezioak: onartutakoan bi prezioak ikusiko dituzu.',
