  'This e-mail link has already been used or has expired. Links work once and only for a short time.': 'Esteka hau erabilita edo iraungita dago. Behin eta denbora laburrez balio dute.',
  'This e-mail already has an account. Sign in, or use “Forgot your password?”.': 'Posta honek kontua du jada. Hasi saioa edo erabili «Pasahitza ahaztu duzu?».',
  'Wrong e-mail or password. Check both, or reset your password.': 'Posta edo pasahitz okerra. Egiaztatu biak edo berrezarri pasahitza.',
  'Please confirm your e-mail first: we sent you a new code.': 'Berretsi lehenik posta: kode berri bat bidali dizugu.',
  'That code is wrong or has expired. Ask for a new one.': 'Kode hori okerra edo iraungita dago. Eskatu berri bat.',
  'Too many tries. Please wait a minute and try again.': 'Saiakera gehiegi. Itxaron minutu bat eta saiatu berriro.',
