  'I read your photo: it is a': 'Zure argazkia irakurri dut: hau da:',
  'I can see an IMEI number on the photo. Send it to the team on WhatsApp and they will find the exact model.': 'IMEI zenbaki bat ikusten dut argazkian. Bidali WhatsApp-eko taldeari eta modelo zehatza aurkituko dute.',
  'I looked closely but couldn’t read a model on this photo. A screenshot of Settings → About phone works best, or just tell me the model.': 'Arretaz begiratu dut, baina ezin izan dut modelorik irakurri argazki honetan. Ezarpenak → Telefonoari buruz pantaila-argazkiak hobeto funtzionatzen du, edo esadazu modeloa.',
  'I can read text on photos, but I couldn’t find a model on this one. Try the label on the box, or type the model, and I’ll take it from there.': 'Argazkietako testua irakur dezaket, baina honetan ez dut modelorik aurkitu. Saiatu kutxaren etiketarekin, edo idatzi modeloa, eta nik jarraituko dut.',
  'Send me a photo with the camera button: a screenshot of Settings → About phone, or the label on the box, works best. I’ll read the model for you.': 'Bidali argazki bat kamera-botoiarekin: onena Ezarpenak → Telefonoari buruz pantaila-argazkia edo kutxaren etiketa da. Nik irakurriko dut modeloa.',
  'Settings → About phone → Model.': 'Ezarpenak → Telefonoari buruz → Modeloa.',
  'Settings → About phone → All specs → Model.': 'Ezarpenak → Telefonoari buruz → Zehaztapen guztiak → Modeloa.',
  'Dial *#06# for the IMEI and send it to us: we find the exact model.': 'Markatu *#06# IMEIa ikusteko eta bidali guri: modelo zehatza aurkituko dugu.',
  'Still about your': 'Oraindik zure honi buruz:',
  'Tell me the part: screen, battery, camera or charging port.': 'Esadazu pieza: pantaila, bateria, kamera edo karga-ataka.',
  'Sure, for which model?': 'Noski, zein modelotarako?',
  'Tell me the model and I’ll find it.': 'Esadazu modeloa eta aurkituko dut.',
  'Which one are you after?': 'Zein bilatzen duzu?',
  'good news, we have these': 'berri ona, hauek ditugu',
  'this is on our shelf': 'hau dago gure apalean',
  'Tap + to add one to your cart.': 'Sakatu + saskira gehitzeko.',
  'Want it fitted? Ask me for the repair price.': 'Jarrita nahi duzu? Galdetu konponketaren prezioa.',
  'We’re in Al Murar, Deira, Dubai.': 'Al Murarren gaude, Deira, Dubai.',
  'Tap below for the map and directions.': 'Sakatu behean mapa eta nola iritsi ikusteko.',
  'Call the shop, message us on WhatsApp or WeChat, or e-mail us. We’re @samelectronics.uae on Instagram, TikTok and Facebook.': 'Deitu dendara, idatzi WhatsApp edo WeChat bidez, edo e-postaz. Instagram, TikTok eta Facebooken @samelectronics.uae gara.',
  'Every part has a warranty that depends on the grade:': 'Pieza bakoitzak kalitatearen araberako bermea du:',
  'Tell me the model and the part, like “A54 battery” or “iPhone 13 screen”, and I’ll show the price of each grade.': 'Esadazu modeloa eta pieza, adibidez «A54 bateria» edo «iPhone 13 pantaila», eta kalitate bakoitzaren prezioa erakutsiko dizut.',
  'The dirham is pegged to the dollar, so this rate stays the same.': 'Dirhama dolarrari lotuta dago, beraz tasa ez da aldatzen.',
