  'Parts, grades, prices, repairs, shipping, opening hours: I know the shop inside out. Spelling mistakes are fine, and I speak your language.': 'Piezak, kalitateak, prezioak, konponketak, bidalketak, ordutegiak: denda buruz dakit. Akatsak ez dira arazo, eta zure hizkuntza hitz egiten dut.',
  'Right now:': 'Orain:',
