  'Trade prices unlock once your trade account is approved. Send a bulk list and we quote it the same day.': 'Handizkako prezioak saltzaile-kontua onartzean irekitzen dira. Bidali zerrenda bat eta egun berean emango dizugu aurrekontua.',
