  'Who makes your part.': 'Nork egiten duen zure pieza.',
  'Who sees it': 'Nork ikusten dituen',
  'Who we are': 'Nor garen',
  'You may return an unused part, in its original packaging with labels and protective films intact, within 7 days of purchase for an exchange or store credit. Screens with removed films are considered used.': 'Erabili gabeko pieza bat itzul dezakezu, jatorrizko paketean, etiketak eta film babesleak oso, erosi eta 7 egunetan, aldaketa edo kreditu baten truke. Filmak kendutako pantailak erabilitzat jotzen dira.',
  'Your rights': 'Zure eskubideak',
  'in plain words.': 'hitz errazetan.',
  'Bring or send it back with the invoice within the warranty. We test it; if it is faulty we replace it or refund you. See the returns policy for the details.': 'Ekarri edo bidali fakturarekin bermearen barruan. Probatzen dugu; akastuna bada, aldatu edo dirua itzultzen dizugu. Xehetasunak itzulketa-politikan.',
  'Prices are in UAE dirhams (AED). Prices shown in the shop do not include VAT; 5% UAE VAT is added at checkout and shown on the tax invoice.': 'Prezioak EAEko dirhametan (AED). Dendako prezioek ez dute BEZa barne; EAEko % 5eko BEZa ordaintzean gehitzen da eta zerga-fakturan agertzen da.',
  'Liability': 'Erantzukizuna',
  'Refunds': 'Itzulketak',
  'You may ask us to hand your order to your own shipper or cargo agent. We pack it and share the paperwork; the shipping cost and the shipper’s terms are between you and your shipper, and responsibility passes to you when we hand the parcel over.': 'Zure eskaera zure garraiolari edo karga-agenteari emateko eska diezagukezu. Paketatu eta paperak partekatzen ditugu; bidalketa-kostua eta baldintzak zure eta zure garraiolariaren artekoak dira, eta erantzukizuna zuregana pasatzen da paketea ematean.',
  'A well-known aftermarket maker with consistent quality and packaging; our usual AAA choice.': 'Kalitate eta paketatze koherentea duen ordezko-fabrikatzaile ezaguna; gure ohiko AAA aukera.',
  'photos of each city arrive with the owner’s pictures': 'hiri bakoitzeko argazkiak jabearen irudiekin iritsiko dira',
  'Sam Electronics: same management, new name.': 'Sam Electronics: zuzendaritza bera, izen berria.',
  'Syria Tell opens in Deira.': 'Syria Tell Deiran irekitzen da.',
