  'This part of the site is still being built. Everything you need is on the home page in the meantime.': 'Webgunearen zati hau eraikitzen ari gara oraindik. Bitartean, behar duzun guztia hasiera-orrian dago.',
  'Open Find My Part': 'Ireki Aurkitu nire pieza',
