  'Compatibility only': 'Bateragarritasuna soilik',
  'Original and compatible parts': 'Jatorrizko pieza eta bateragarriak',
  'Four kinds, named after phone parts': 'Lau mota, telefono-piezen izenekin',
  'Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates. Contact: samelectronics.uae@gmail.com.': 'Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates. Harremana: samelectronics.uae@gmail.com.',
  'These terms apply to every sale by Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates ("Sam Electronics", "we"), in the shop, on this website, on WhatsApp or by phone.': 'Baldintza hauek Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates-k («Sam Electronics», «gu») egiten duen salmenta orori aplikatzen zaizkio: dendan, webgune honetan, WhatsApp bidez edo telefonoz.',
  'Prices, stock, delivery times and offers depend on where you are. Please do not hide your location (for example with a VPN) when you browse or order; if you do, what you see may not apply to you and we may ask you to confirm your location before we confirm an order.': 'Prezioak, stocka, entrega-epeak eta eskaintzak non zauden araberakoak dira. Ez ezkutatu zure kokapena (adibidez VPN batekin) nabigatzean edo eskatzean; hala eginez gero, ikusten duzuna agian ez da zuretzat izango, eta eskaera berretsi aurretik kokapena berresteko eska diezazukegu.',
  'Everything on this website and in our systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by UAE copyright law (Federal Decree-Law No. 38 of 2021). You may keep a copy for your own reference; copying, sharing or publishing it needs our written permission.': 'Webgune honetako eta gure sistemetako guztia (argazkiak, diseinuak, testuak, prezioak eta datuak) Sam Electronicsena da, eta AEBko egile-eskubideen legeak babesten du (2021eko 38. zenbakiko Lege Dekretu Federala). Kopia bat gorde dezakezu zure kontsultarako; kopiatzeko, partekatzeko edo argitaratzeko gure idatzizko baimena behar da.',
  'Account details (name, e-mail, phone, password stored encrypted), company details you add, orders and invoices, messages you send us, Samsoom chats if you keep them with your account, and basic technical data (device, pages visited) to keep the site working.': 'Kontuaren datuak (izena, posta, telefonoa, zifratuta gordetako pasahitza), gehitzen dituzun enpresa-datuak, eskaerak eta fakturak, bidaltzen dizkiguzun mezuak, Samsoomekin izandako txatak kontuan gordetzen badituzu, eta oinarrizko datu teknikoak (gailua, bisitatutako orriak) webguneak funtziona dezan.',
  'Ask for a copy, a correction or deletion of your data, or object to its use, using the privacy form on the contact page. We answer within 30 days, in line with the UAE personal data protection law.': 'Eskatu zure datuen kopia, zuzenketa edo ezabaketa, edo aurka egin haien erabilerari, harremanetarako orriko pribatutasun-inprimakiaren bidez. 30 eguneko epean erantzungo dugu, AEBko datu pertsonalak babesteko legearen arabera.',
  'Battery (essential, always on): your cart, language, sign-in and these choices. Kept until you clear them; sign-in until you sign out.': 'Bateria (ezinbestekoak, beti aktibo): saskia, hizkuntza, saioa eta aukera hauek. Ezabatu arte gordetzen dira; saioa amaitu arte.',
  'Memory Chip (preferences): currency, sounds, recent searches, starred parts and your devices. Kept 12 months.': 'Memoria-txipa (hobespenak): moneta, soinuak, azken bilaketak, markatutako piezak eta zure gailuak. 12 hilabetez gordetzen dira.',
  'Diagnostics (anonymous statistics): which pages are opened and how fast they load, never your name or contact. Kept 13 months.': 'Diagnostikoa (estatistika anonimoak): zein orri irekitzen diren eta zein azkar kargatzen diren, inoiz ez zure izena edo harremana. 13 hilabetez gordetzen dira.',
  'Antenna (marketing and offers): the kinds of parts you look at, to show matching offers. Kept 6 months.': 'Antena (marketina eta eskaintzak): begiratzen dituzun pieza motak, bat datozen eskaintzak erakusteko. 6 hilabetez gordetzen dira.',
  'The banner asks once, after the welcome. Change your choice any time with "Cookie settings" at the bottom of every page, or clear everything in your browser: the site will simply forget your cart and preferences on that device. Each choice is saved with its date.': 'Bannerrak behin galdetzen du, ongietorriaren ondoren. Aldatu zure aukera edonoiz orri bakoitzaren beheko «Cookie ezarpenak» erabiliz, edo garbitu dena nabigatzailean: webguneak saskia eta hobespenak ahaztuko ditu gailu horretan. Aukera bakoitza bere datarekin gordetzen da.',
  'Brand names, model names and logos (such as Apple, Samsung, Xiaomi, Huawei and others) belong to their owners. We use them only to show which phones a part fits. Sam Electronics is an independent parts seller and repair shop, and is not affiliated with, authorised by or endorsed by these brands unless a page says so.': 'Marka-izenak, modelo-izenak eta logotipoak (Apple, Samsung, Xiaomi, Huawei eta beste batzuk, adibidez) beren jabeenak dira. Pieza bat zein telefonotan sartzen den erakusteko soilik erabiltzen ditugu. Sam Electronics pieza-saltzaile eta konponketa-tailer independentea da, eta ez dago marka horiei lotuta, ez dute baimendu ezta babestu ere, orri batek kontrakoa esaten ez badu.',
  'Every part is labelled with its quality and its maker. "Original" and "Service Pack" mean parts made for the brand; every other quality is a compatible part from the maker named on the label.': 'Pieza bakoitzak bere kalitatea eta fabrikatzailea ditu etiketan. «Original» eta «Service Pack» markarentzat egindako piezak dira; beste edozein kalitate etiketan aipatutako fabrikatzailearen pieza bateragarria da.',
  'LIVE PARTS BOARD · LIVE FEED': 'PIEZA-TAULA ZUZENEAN · ZUZENEKO JARIOA',
  'REPAIR SHOP': 'KONPONKETA-TAILERRA',
