  'Register online, your first purchase activates it.': 'Erregistratu sarean; zure lehen erosketak aktibatzen du.',
  'For shops and traders': 'Denda eta merkatarientzat',
  'Apply with your trade licence; we activate it by hand.': 'Eskatu zure merkataritza-lizentziarekin; eskuz aktibatzen dugu.',
  'Visit the counter': 'Etorri mostradorera',
  'Live chat with the team': 'Zuzeneko txata taldearekin',
  'Right on this page': 'Orri honetan bertan',
  'Goes to the team inbox': 'Taldearen sarrera-ontzira doa',
  'Our assistant, any time': 'Gure laguntzailea, edozein ordutan',
  'Parts, grades, repairs, prices': 'Piezak, kalitateak, konponketak, prezioak',
  'Read every working day': 'Lanegun guztietan irakurria',
  'We reply by e-mail, usually the same day.': 'Posta bidez erantzuten dugu, normalean egun berean.',
  'Walk in, no appointment': 'Etorri, hitzordurik gabe',
  'Team online': 'Taldea linean',
