  'Leave a message': 'Utzi mezu bat',
  'Batteries, flex cables, small parts': 'Bateriak, flexak, pieza txikiak',
  'Most screens, cameras, back glass': 'Pantaila, kamera eta atzeko beira gehienak',
  'Original screens on flagship phones': 'Jatorrizko pantailak goi-mailako telefonoetan',
  'Tell us when, we print your job card.': 'Esan noiz, eta zure lan-txartela inprimatuko dugu.',
  'SHIPPING ORDER': 'BIDALKETA-AGINDUA',
  'Tap “Model Number” once: it changes to a code that starts with A (for example A2846).': 'Sakatu behin «Modelo-zenbakia»: A-z hasten den kode bihurtzen da (adibidez A2846).',
  'Parts, repairs, trade, shipping and payments. Search, or pick a topic. Still stuck? Samsoom is one tap away.': 'Piezak, konponketak, profesionalak, bidalketak eta ordainketak. Bilatu edo aukeratu gai bat. Zalantzak? Samsoom ukitu batera dago.',
  'Pay your way.': 'Ordaindu zure erara.',
  'Every way you can pay us today, in the shop, online and from abroad. Prices are in AED; card payments are charged in AED.': 'Gaur ordaintzeko bide guztiak: dendan, sarean eta atzerritik. Prezioak AEDtan; txartel-ordainketak AEDtan kobratzen dira.',
  'Online card payments go through a secure payment page; we never see or keep your card details.': 'Sareko txartel-ordainketak orri seguru batetik doaz; ez dugu inoiz zure txartelaren daturik ikusten edo gordetzen.',
  'We never ask for your card number on WhatsApp or by e-mail.': 'Ez dugu inoiz txartel-zenbakia eskatzen WhatsApp bidez edo postaz.',
  'Need another way to pay? Ask us on WhatsApp and we will tell you what is possible.': 'Beste ordainketa-modu bat behar duzu? Galdetu WhatsApp bidez eta esango dizugu zer den posible.',
  'When your internet connection says you are in a different place than your device’s clock, you are most likely using a VPN or a proxy.': 'Konexioak gailuaren erlojuak ez bezalako leku bat adierazten duenean, ziurrenik VPN edo proxy bat erabiltzen ari zara.',
  'Prices, stock, delivery times and offers on this website depend on where you really are. With a hidden location, what you see may not apply to you, and we may ask you to confirm your location before we confirm an order.': 'Webgune honetako prezioak, stocka, epeak eta eskaintzak benetan non zauden araberakoak dira. Kokapena ezkutatuta, ikusten duzuna agian ez da zuretzat, eta eskaera berretsi aurretik kokapena berresteko eska diezazukegu.',
  'Our terms of use ask visitors not to hide their location when browsing or ordering. If you are simply travelling, choose “I am travelling” and carry on: nothing else changes.': 'Gure erabilera-baldintzek eskatzen dute nabigatzean edo eskatzean kokapena ez ezkutatzea. Bidaian besterik ez bazaude, aukeratu «Bidaian nago» eta jarraitu: ez da beste ezer aldatzen.',
  'We only compare two time zones. We never store your IP address.': 'Bi ordu-eremu baino ez ditugu alderatzen. Ez dugu inoiz zure IP helbidea gordetzen.',
  'Browsers can only see the screenshot keys on computers (Print Screen, ⌘⇧3/4/5, Win+Shift+S). When we see one, this notice appears once and the team is told which page it was.': 'Nabigatzaileek ordenagailuetan soilik ikusten dituzte pantaila-argazki teklak (Impr Pant, ⌘⇧3/4/5, Win+Shift+S). Bat ikusten dugunean, ohar hau behin agertzen da eta taldeari zein orri zen jakinarazten zaio.',
  'If you took it for another reason, you can safely ignore the notice. For permission, write to us from the Contact page.': 'Beste arrazoi batengatik egin baduzu, oharra ez ikusiarena egin dezakezu. Baimena eskatzeko, idatzi harremanetarako orritik.',
