  'Shop commercial: screens, every grade, battery week, trade prices, worldwide shipping.': 'Dendaren iragarkia: pantailak, kalitate guztiak, bateria astea, saltzaile prezioak, mundu osorako bidalketak.',
  'The big box plays our latest offers. Pick a tab, a part or a brand and it shows that topic\'s own deals.': 'Kutxa handiak azken eskaintzak erakusten ditu. Aukeratu fitxa, pieza edo marka bat eta horren eskaintzak ikusiko dituzu.',
  'The coloured tag is the quality (Original, OLED, Incell, AAA and more). The dark tag with a light is who made it.': 'Etiketa koloreduna kalitatea da (Original, OLED, Incell, AAA…). Argidun etiketa ilunak egilea adierazten du.',
  'Star a part to keep it in My Bench. The two-cards button adds it to Compare: up to three parts side by side.': 'Izarra jarri pieza bati My Bench-en gordetzeko. Bi txarteleko botoiak Alderatu-ra gehitzen du: hiru pieza arte.',
  'Sort by price, newest or best match, and switch between the grid and the list.': 'Ordenatu prezioz, berritasunez edo egokitasunez, eta aldatu sareta eta zerrenda artean.',
  'Repair shops and traders: apply once, and every part shows your trade price.': 'Konponketa dendak eta saltzaileak: eskatu behin, eta pieza guztiek zure prezioa erakutsiko dute.',
  'The questions people ask most, answered in one place. Still stuck? Ask Samsoom.': 'Galdera ohikoenak, leku bakarrean. Zalantzarik? Galdetu Samsoomi.',
