  'Chats are kept only on this device.': 'Txatak gailu honetan bakarrik gordetzen dira.',
  'Download my chats': 'Deskargatu nire txatak',
  'Sure, let us find your order. I opened the order tracker below.': 'Noski, bila dezagun zure eskaera. Jarraipena behean ireki dut.',
  'Happy to book you in. Pick the problem, a day and a time below.': 'Pozik. Aukeratu arazoa, eguna eta ordua behean.',
  'I can watch that for you. Find the part below and I will ring the bell when it is back.': 'Nik zainduko dut. Bilatu pieza behean eta kanpaia joko dut itzultzean.',
  'I can watch the price for you. Find the part below.': 'Prezioa zainduko dut. Bilatu pieza behean.',
  'Let us check what fits. Tell me your phone below.': 'Ikus dezagun zer datorren bat. Esan zure telefonoa behean.',
  'Paste your parts list below, one part per line.': 'Itsatsi zure pieza zerrenda behean, pieza bat lerroko.',
  'Parts that fit your': 'Zure gailuari egokitzen zaizkion piezak:',
  'Fits': 'Egokia',
  'made for this exact model, no adapters': 'modelo zehatz honetarako egina, egokitzailerik gabe',
  'your phone is in My devices for next time': 'zure telefonoa Nire gailuak atalean dago hurrengorako',
  'COMPLAINTS': 'KEXAK',
  'Something went wrong?': 'Zerbait gaizki joan da?',
  'Tell us everything.': 'Kontatu dena.',
  'Every complaint gets a case number and goes straight to the management team. We answer within one working day.': 'Kexa bakoitzak kasu zenbaki bat jasotzen du eta zuzendaritzara doa. Lanegun batean erantzuten dugu.',
  'What is it about?': 'Zertaz da?',
  'A part or product': 'Pieza edo produktu bat',
