  'Publishing, reselling or editing them, or using our photos and prices elsewhere, needs our written permission.': 'Argitaratzeko, birsaltzeko, editatzeko edo gure argazki eta prezioak beste nonbait erabiltzeko idatzizko baimena behar da.',
