  'Save the phones you fix most. I will mark every part that fits them.': 'Gorde gehien konpontzen dituzun telefonoak. Haiei egokitzen zaien pieza guztiak markatuko ditut.',
  'Screenshots are for your own use, and every one carries our watermark. Sharing or publishing them needs our permission.': 'Pantaila-argazkiak zure erabilerarako dira, eta denek daramate gure ur-marka. Partekatzeko edo argitaratzeko gure baimena behar da.',
  'Every conversation you had with Samsoom on this device. Open one to carry on.': 'Gailu honetan Samsoomekin izan dituzun elkarrizketa guztiak. Ireki bat jarraitzeko.',
  'Every order, with its status. We confirm stock and price on WhatsApp before you pay.': 'Eskaera bakoitza bere egoerarekin. Stocka eta prezioa WhatsApp bidez berresten ditugu ordaindu aurretik.',
  'Everything the bell told you: orders, repairs, stock alerts and offers.': 'Kanpaiak esan dizun guztia: eskaerak, konponketak, stock-alertak eta eskaintzak.',
  'The phones you fix or own. The shop marks every part that fits them, and Find My Part opens on them.': 'Konpontzen edo dituzun telefonoak. Dendak haiei egokitzen zaien pieza oro markatzen du, eta Find My Part haiekin irekitzen da.',
  'Your cart, the parts you saved for later, your stars and your price & stock alerts.': 'Zure saskia, gerorako gordetako piezak, zure izarrak eta prezio- eta stock-alertak.',
  'Your details, how we reach you, and your language.': 'Zure datuak, nola harremanetan jarri zurekin eta zure hizkuntza.',
  'Your repair tickets with their progress, and a warranty check for any order or repair.': 'Zure konponketa-txartelak aurrerapenarekin, eta berme-egiaztapena edozein eskaera edo konponketarako.',
  'Add the businesses you buy for: details, trade licence, TRN and every location. Orders can be placed for a company.': 'Gehitu erosten duzun enpresak: datuak, merkataritza-lizentzia, TRN eta kokapen guztiak. Eskaerak enpresa baten izenean egin daitezke.',
  'Write to the team here: they answer from the Control Room during opening hours, and you get an e-mail when they do.': 'Idatzi taldeari hemen: Control Room-etik erantzuten dute irekiera-orduetan, eta mezu elektroniko bat jasoko duzu.',
  'We will message you when the price drops or stock is back (e-mail alerts start when the database is connected).': 'Prezioa jaisten denean edo stocka itzultzen denean idatziko dizugu (posta-alertak datu-basea konektatzean hasiko dira).',
